### Full Implementation

```typescript
export interface RetryOptions {
  /** Maximum number of retry attempts (0 = no retries) */
  maxRetries: number;
  /** Base delay in milliseconds before the first retry */
  baseDelayMs: number;
  /** Upper bound for backoff delay in milliseconds */
  maxDelayMs: number;
}

export interface QueueResult<T> {
  successes: number;
  failures: number;
  errors: Array<{ item: T; error: Error; retries: number }>;
}

/**
 * Cancellable sleep that respects AbortSignal.
 */
async function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, ms);
    if (signal?.aborted) {
      clearTimeout(timer);
      reject(new Error('Aborted'));
      return;
    }
    const onAbort = () => {
      clearTimeout(timer);
      reject(new Error('Aborted'));
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Calculates exponential backoff with multiplicative jitter.
 * Prevents thundering herd while keeping delays predictable.
 */
function calculateBackoff(attempt: number, opts: RetryOptions): number {
  const exponential = opts.baseDelayMs * Math.pow(2, attempt);
  const jittered = exponential * (0.5 + Math.random());
  return Math.min(jittered, opts.maxDelayMs);
}

/**
 * Token Bucket rate limiter.
 * Allows bursts up to `rate` tokens, then refills at `rate` tokens/second.
 */
class TokenBucket {
  private tokens: number;
  private lastRefill: number;
  private readonly rate: number;

  constructor(rate: number) {
    this.rate = rate;
    this.tokens = rate; // Start full to allow immediate burst
    this.lastRefill = Date.now();
  }

  private refill(): void {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.rate, this.tokens + elapsed * this.rate);
    this.lastRefill = now;
  }

  async acquire(signal?: AbortSignal): Promise<void> {
    while (true) {
      if (signal?.aborted) throw new Error('Aborted');
      this.refill();
      if (this.tokens >= 1) {
        this.tokens -= 1;
        return;
      }
      // Wait until at least 1 token is available
      const waitMs = ((1 - this.tokens) / this.rate) * 1000;
      await sleep(waitMs, signal);
    }
  }
}

/**
 * Rate-limited, concurrent async job queue with retry and failure isolation.
 */
export class AsyncJobQueue<T, R> {
  private readonly limiter: TokenBucket;
  private readonly retryOpts: RetryOptions;
  private readonly concurrency: number;

  constructor(concurrency: number, maxRPS: number, retryOpts: RetryOptions) {
    this.concurrency = concurrency;
    this.limiter = new TokenBucket(maxRPS);
    this.retryOpts = retryOpts;
  }

  async run(
    items: T[],
    processor: (item: T, signal: AbortSignal) => Promise<R>,
    signal: AbortSignal
  ): Promise<QueueResult<T>> {
    const errors: QueueResult<T>['errors'] = [];
    let successes = 0;
    let index = 0;

    const worker = async (): Promise<void> => {
      while (true) {
        if (signal.aborted) break;
        // JS event loop guarantees index++ is atomic across async yields
        const i = index++;
        if (i >= items.length) break;

        const item = items[i];
        try {
          const { retries } = await this.executeWithRetry(item, processor, signal);
          successes++;
        } catch (err) {
          // AbortError propagates to break the worker loop gracefully
          if (err instanceof Error && err.message === 'Aborted') break;
          errors.push({
            item,
            error: err instanceof Error ? err : new Error(String(err)),
            retries: this.retryOpts.maxRetries,
          });
        }
      }
    };

    // Spin up fixed worker pool
    const workers = Array.from({ length: this.concurrency }, () => worker());
    await Promise.all(workers);

    return { successes, failures: errors.length, errors };
  }

  private async executeWithRetry(
    item: T,
    processor: (item: T, signal: AbortSignal) => Promise<R>,
    signal: AbortSignal
  ): Promise<{ result: R; retries: number }> {
    let lastError: Error | undefined;

    for (let attempt = 0; attempt <= this.retryOpts.maxRetries; attempt++) {
      if (signal.aborted) throw new Error('Aborted');

      try {
        await this.limiter.acquire(signal);
        const result = await processor(item, signal);
        return { result, retries: attempt };
      } catch (err) {
        lastError = err instanceof Error ? err : new Error(String(err));

        // Never retry abort signals
        if (lastError.message === 'Aborted') throw lastError;

        if (attempt < this.retryOpts.maxRetries) {
          const delay = calculateBackoff(attempt, this.retryOpts);
          await sleep(delay, signal);
        }
      }
    }
    throw lastError!;
  }
}
```

### Usage Example

```typescript
async function main() {
  const controller = new AbortController();

  // Simulate an external shutdown hook (e.g., SIGTERM, UI cancel button)
  setTimeout(() => {
    console.log('Initiating graceful shutdown...');
    controller.abort();
  }, 3000);

  const queue = new AsyncJobQueue<string, number>(
    5, // Max concurrent workers
    10, // Max requests per second
    { maxRetries: 3, baseDelayMs: 200, maxDelayMs: 2000 }
  );

  const items = Array.from({ length: 50 }, (_, i) => `etl-job-${i}`);

  const processor = async (item: string, signal: AbortSignal) => {
    // Simulate I/O bound ETL step
    await sleep(50 + Math.random() * 100, signal);

    // Simulate transient failures (~20% chance)
    if (Math.random() < 0.2) {
      throw new Error(`Transient DB timeout for ${item}`);
    }
    return item.length;
  };

  const result = await queue.run(items, processor, controller.signal);

  console.log(`Completed: ${result.successes} successes, ${result.failures} failures`);
  if (result.errors.length > 0) {
    console.log('Failed items:', result.errors.map(e => e.item));
  }
}

main().catch(console.error);
```

### Design Trade-offs & Notes

| Feature | Trade-off / Rationale |
|---------|----------------------|
| **Token Bucket vs Leaky Bucket** | Chose token bucket for natural burst tolerance (starts full) and simpler math. Leaky buckets enforce stricter constant throughput but require more complex queueing logic. For ETL, burst tolerance at pipeline start is usually desirable. |
| **Concurrency Model** | Uses a shared `index` counter across `async` workers. Relies on JavaScript's single-threaded event loop where `index++` is synchronous and atomic. Safe for Node.js/Browser, but **not** suitable for multi-process/WorkerThread environments without an external coordinator. |
| **Jitter Strategy** | Uses multiplicative jitter `(0.5 + Math.random())`. This halves the risk of synchronized retries compared to pure exponential backoff, while keeping delays bounded and predictable. "Full jitter" (`Math.random() * max`) is better for distributed systems but adds unnecessary variance for a single-process ETL. |
| **Failure Isolation** | Errors are caught per-item and collected. The pipeline never aborts on individual failures. This maximizes throughput for overnight runs but means you must handle partial results downstream. No checkpointing is implemented; for pipelines >12hrs, you'd need external state persistence. |
| **Cancellation Semantics** | `AbortSignal` is checked synchronously before each step and asynchronously during waits. The processor **must** also respect the signal (e.g., pass it to `fetch` or `axios`). If the processor ignores it, cancellation only occurs between items. `AbortError` is fast-pathed to skip retries entirely. |
| **Precision & Drift** | `Date.now()` is used for token refill calculations. Clock drift or GC pauses can cause minor rate inaccuracies, but this is negligible for ETL workloads where ±5% variance is acceptable. |
| **Memory Footprint** | `errors` array stores full error objects and item references. For millions of items, consider streaming errors to disk/DB instead of accumulating in memory. |

This implementation is optimized for predictable, high-throughput batch processing with strict external rate limits (e.g., API quotas, database connection pools, or downstream service limits). It avoids heavy dependencies while maintaining type safety and graceful degradation under failure or cancellation.

