### Full Implementation

```typescript
// ─── Types & Interfaces ───────────────────────────────────────────────────────

export type JobFn<T, R> = (input: T, signal: AbortSignal) => Promise<R>;

export interface Job<T, R> {
  id: string;
  input: T;
  fn: JobFn<T, R>;
}

export interface QueueConfig {
  maxConcurrency: number;
  maxRPS: number;
  baseRetryDelayMs: number;
  maxRetries: number;
  maxRetryDelayMs: number;
  jitterMs: number;
}

export interface JobResult<R> {
  id: string;
  success: boolean;
  data?: R;
  error?: Error;
}

export interface BatchResult<R> {
  successes: number;
  failures: number;
  results: JobResult<R>[];
  errors: Map<string, Error>;
}

// ─── Core Engine ──────────────────────────────────────────────────────────────

export class JobQueue<T, R> {
  private readonly config: QueueConfig;
  private readonly tokenBucket: TokenBucket;

  constructor(config: QueueConfig) {
    this.config = config;
    this.tokenBucket = new TokenBucket(config.maxRPS);
  }

  /**
   * Processes a batch of jobs with concurrency control, rate limiting, 
   * retry logic, and graceful cancellation.
   */
  async process(jobs: Job<T, R>[], signal: AbortSignal): Promise<BatchResult<R>> {
    const stats: BatchResult<R> = {
      successes: 0,
      failures: 0,
      results: [],
      errors: new Map<string, Error>(),
    };

    const pending = [...jobs];
    const running = new Set<Promise<void>>();

    while (pending.length > 0 || running.size > 0) {
      if (signal.aborted) break;

      // Dispatch jobs up to the concurrency limit
      while (running.size < this.config.maxConcurrency && pending.length > 0) {
        const job = pending.shift()!;
        const p = this.runJob(job, signal, stats);
        running.add(p);
        p.finally(() => running.delete(p));
      }

      if (running.size === 0) break;

      // Wait for at least one job to settle before re-evaluating dispatch
      await Promise.race(running);
    }

